function REGION(act, S, sample):
    R <- empty set
    for x in sample:
        if act(x) in S:
            R <- R union {x}
    return R

function CELLS(act, sample):
    cells <- empty map (pattern -> set of points)
    for x in sample:
        p <- act(x)
        cells[p] <- cells[p] union {x}
    return cells   # keys = realized patterns

function REALIZABILITY(act, sample, k):
    realized <- { act(x) : x in sample }
    allP <- all bit-strings of length k
    missing <- allP \ realized
    surjective <- (missing is empty)
    return (surjective, missing)

