from __future__ import annotations
from itertools import product
from typing import Callable, Tuple, Set, Sequence

Pattern = Tuple[bool, ...]
Point = Tuple[float, ...]

def realizability(act: Callable[[Point], Pattern],
                  sample: Sequence[Point],
                  k: int) -> Tuple[bool, Set[Pattern]]:
    """Return (all-patterns-realized?, set of missing patterns)."""
    realized = {act(x) for x in sample}
    all_patterns = {tuple(b) for b in product([False, True], repeat=k)}
    missing = all_patterns - realized
    return (len(missing) == 0, missing)
